contract_clause_fact(contrato_ocs_179_2021, clausula_oitava_equilibrio_economico_financeiro_contrato, motivos_revisao, ['fato imprevisível', 'fato previsível, porém, de consequências incalculáveis', 'força maior', 'caso fortuito', 'fato do príncipe'], 'Parágrafo Segundo').
contract_clause_fact(contrato_ocs_179_2021, clausula_oitava_equilibrio_economico_financeiro_contrato, documentos_revisao, ['atos normativos', 'lista de preço de fabricantes', 'notas fiscais de aquisição de matérias-primas', 'de transporte de mercadorias', 'planilhas de custos unitários'], 'Parágrafo Segundo').
